def render(description, qty, unit_cents, total_cents, currency, decimals, separator):
    unit = str(unit_cents // 100) + separator + str(unit_cents % 100).zfill(decimals) + " " + currency
    total = str(total_cents // 100) + separator + str(total_cents % 100).zfill(decimals) + " " + currency
    return description + " | " + str(qty) + " x " + unit + " = " + total


def format_line(line):
    return render(line["description"], line["qty"], line["unit_cents"], line["qty"] * line["unit_cents"], line["currency"], 2, ".")
